/* Diktat Hans · Bab 12 Matahari dan Anggota Tata Surya */
(function () {
const R = String.raw, E = (n, q, a, s, note) => ({ n, q, a, s, note });
OSN.hans({
 no: 12, title: 'Matahari dan Anggota Tata Surya', acad: ['tatasurya', 'bumibulan'],
 summary: R`Bab terpanjang di diktat: Matahari (sumber energi, struktur dalam, fotosfer–kromosfer–korona, bintik dan siklus 11/22 tahun, rotasi diferensial dan dinamo, flare, CME, aurora), lalu planet satu per satu (Merkurius sampai Neptunus, Bumi dan Bulan dibahas paling rinci), benda kecil (asteroid, komet, meteoroid, objek sabuk Kuiper), teori pembentukan tata surya, dan keputusan IAU 2006 tentang Pluto. Kuncinya bukan menghafal angka, tetapi memahami <i>mengapa</i>: mengapa korona panas, mengapa Venus neraka sedangkan Bumi nyaman, mengapa komet berekor menjauhi Matahari.`,
 topics: [
  { h: 'Dari mana energi Matahari?', body: R`<p>Matahari memancarkan \(L_\odot = 3{,}85\times10^{26}\) W dan sudah bersinar ±4,6 miliar tahun (umur meteorit dan batuan Bumi). Tiga kandidat sumber energi diuji dengan "umur yang bisa dicapai" \(t = E/L\):</p><ul><li><b>Kimia</b> (pembakaran): energi per kg ~10⁷ J → hanya bertahan beberapa ribu tahun. Gugur.</li><li><b>Pengerutan gravitasi</b> (Kelvin–Helmholtz): \(t_{KH}\approx GM^2/(RL)\approx 3\times10^7\) tahun (buku: 25 juta tahun). Terlalu pendek, walau inilah sumber energi Matahari saat masih protobintang.</li><li><b>Fusi nuklir</b>: 4 ¹H → ⁴He melepas 0,7% massanya (\(E = \Delta m\,c^2\)). Dengan ~10% massa Matahari terbakar di inti, \(t\approx 0{,}1\times0{,}007\,M c^2/L \approx 10^{10}\) tahun. Cocok!</li></ul><p>Akibatnya Matahari kehilangan massa \(\dot M = L/c^2 \approx 4{,}3\times10^9\) kg tiap detik, tetapi selama 5 miliar tahun itu baru ~0,03% massanya. Bukti langsung fusi: <b>neutrino</b> Matahari yang tertangkap detektor di Bumi.</p>` },
  { h: 'Struktur dalam dan atmosfer Matahari', body: R`<p><b>Inti</b> (0–0,25 R☉, ~15 juta K): fusi. <b>Zona radiatif</b> (sampai 0,71 R☉): energi dibawa foton yang terus diserap dan dipancarkan ulang, "berjalan acak" ~10⁵ tahun. <b>Zona konveksi</b> (0,71–1 R☉): gas terlalu kedap sehingga energi diangkut aliran naik-turun. Bagian dalam ini "dilihat" lewat <b>helioseismologi</b> (osilasi permukaan ±5 menit) dan neutrino.</p><p><b>Fotosfer</b> (tebal ~400 km, 5800 K) adalah lapisan tempat gas berubah dari kedap menjadi tembus pandang, sehingga tepi Matahari tampak tajam. Di sini tampak <b>granulasi</b> (puncak sel konveksi ~1000 km, umur menit), <b>supergranulasi</b> (~30 000 km, umur ~1 hari, terlihat di Dopplergram), dan <b>penggelapan tepi</b>: di tepi piringan garis pandang kita miring sehingga hanya menembus lapisan yang lebih tinggi dan lebih dingin → lebih redup dan lebih merah.</p><p><b>Kromosfer</b> (~2000 km, suhu naik sampai ~10⁴ K) berwarna merah karena memancarkan garis emisi Hα 656,3 nm (transisi n = 3 → 2 hidrogen); tampak <b>spikula</b> di batas supergranula. <b>Korona</b> sangat renggang tetapi bersuhu 1–2 juta K, mengembang terus menjadi <b>angin surya</b>. Kromosfer dan korona jauh lebih redup daripada fotosfer, sehingga hanya terlihat saat gerhana total, dengan koronagraf, atau di sinar-X/EUV (di mana fotosfer yang "dingin" justru gelap). Pemanasan korona tidak mungkin oleh konduksi atau radiasi dari bawah (panas tak mengalir dari dingin ke panas); sumbernya energi medan magnet (gelombang Alfvén, flare kecil/nanoflare).</p>`, fig: 'matahari' },
  { h: 'Bintik Matahari dan siklus 11 tahun', body: R`<p>Bintik adalah daerah fotosfer yang ~1500–2000 K lebih dingin (umbra gelap, penumbra lebih terang) karena medan magnet kuat (~0,3 T) menghambat konveksi yang membawa panas. Bukti medannya: <b>efek Zeeman</b>, garis spektrum di bintik terpecah menjadi beberapa komponen yang jaraknya sebanding dengan kuat medan. Bintik muncul berkelompok, berpasangan seperti kutub-kutub magnet batang; bintik besar bisa beberapa kali ukuran Bumi dan bertahan berhari-hari hingga beberapa bulan.</p><p>Kegiatan bintik diukur dengan <b>bilangan Wolf</b> \(R = k(10g + f)\), g = jumlah kelompok, f = jumlah bintik individual, k = faktor koreksi pengamat/alat (buku menulis \(10g+k\) dengan k = jumlah bintik). R naik turun dengan periode rata-rata ~11 tahun. Awal siklus bintik muncul di lintang ±30°–35°; makin lama makin dekat ekuator (<b>hukum Spörer</b>), membentuk <b>diagram kupu-kupu</b>. Bintik siklus baru di lintang tinggi muncul ketika bintik siklus lama masih ada di dekat ekuator, itulah tanda awal siklus. <b>Hukum Hale</b>: dalam satu belahan, semua bintik pendahulu berpolaritas sama, berlawanan dengan belahan lain, dan pola ini berbalik tiap siklus, sehingga siklus magnetik lengkap 22 tahun.</p>`, lab: 'kupu' },
  { h: 'Rotasi diferensial dan dinamo Babcock', body: R`<p>Melacak bintik melintasi piringan memberi periode rotasi ~25 hari di ekuator dan ~35 hari dekat kutub (cara lain: efek Doppler di tepi timur dan barat). Matahari adalah fluida, jadi tidak berotasi sebagai benda tegar. Rotasi diferensial ini menarik garis medan magnet yang semula membujur utara–selatan sehingga tergulung melingkari Matahari. Medan yang dimampatkan menjadi kuat, gas di dalam tabung fluks menjadi lebih renggang dan mengapung, lalu menembus fotosfer sebagai pasangan bintik. Pasangan bintik yang meluruh kemudian memindahkan fluks ke kutub dan membalik medan global (model <b>Babcock–Leighton</b>).</p>`, lab: 'dinamo' },
  { h: 'Aktivitas Matahari dan cuaca antariksa', body: R`<ul><li><b>Busur korona</b>: plasma panas yang mengikuti garis medan berbentuk busur, berpijak di dua daerah berpolaritas berlawanan.</li><li><b>Filamen dan prominensa</b>: benda yang sama. Gas kromosfer yang lebih dingin dan rapat ditopang medan magnet di korona; dilihat di depan piringan tampak sebagai jalur gelap (filamen), dilihat di tepi dengan latar langit gelap tampak terang (prominensa). Tenang (quiescent, berminggu-minggu) atau erupsi (beberapa jam).</li><li><b>Plage</b>: daerah terang di kromosfer di sekitar kelompok bintik (fakula di fotosfer).</li><li><b>Flare</b>: pelepasan mendadak energi magnet (rekoneksi) di daerah aktif, memancar di seluruh spektrum dari radio sampai gamma. Energi dilepas di korona lalu memanaskan kromosfer (terlihat di Hα) dan kadang fotosfer (flare cahaya putih). Lebih sering saat siklus maksimum.</li><li><b>CME</b> (lontaran massa korona): miliaran ton plasma dan medan magnet dilempar ~500–2000 km/s, mencapai Bumi dalam 1–4 hari. Ditambah partikel energetik flare, ini mengganggu komunikasi radio, GPS, satelit, jaringan listrik, dan astronot, serta memicu <b>aurora</b> (di lintang tinggi, sekitar oval aurora) ketika partikel yang mengalir sepanjang garis medan Bumi menumbuk atom O dan N di atmosfer atas. Karena itu sistem peringatan dini cuaca antariksa memang perlu.</li></ul>` },
  { h: 'Mengelompokkan planet', body: R`<p>Delapan planet: Merkurius, Venus, Bumi, Mars (planet dalam/terestrial) dan Jupiter, Saturnus, Uranus, Neptunus (planet luar/Jovian), dipisahkan sabuk asteroid. Inferior = di dalam orbit Bumi (Merkurius, Venus), superior = di luar.</p><div class="tablewrap"><table><tr><th>Sifat</th><th>Terestrial</th><th>Jovian</th></tr><tr><td>Ukuran, massa</td><td>kecil</td><td>besar (15–318 M⊕)</td></tr><tr><td>Kerapatan</td><td>3,9–5,5 g/cm³</td><td>0,7–1,6 g/cm³</td></tr><tr><td>Komposisi</td><td>batuan + logam</td><td>H, He, es</td></tr><tr><td>Atmosfer</td><td>tipis, sekunder (CO₂, N₂)</td><td>tebal, primer (H₂, He)</td></tr><tr><td>Rotasi</td><td>lambat</td><td>cepat (~10–17 jam), pepat</td></tr><tr><td>Satelit, cincin</td><td>sedikit, tanpa cincin</td><td>banyak, bercincin</td></tr><tr><td>Panas dalam</td><td>kecil</td><td>besar (kecuali Uranus)</td></tr></table></div><p>Pembagian ini dijelaskan oleh <b>garis salju</b> di cakram protoplanet: di dekat Matahari hanya bahan tahan panas (logam, silikat) yang mengembun, jadi planetnya kecil; di luar ~3–4 SA es juga mengembun, inti tumbuh cepat sampai ~10 M⊕ dan sempat menarik gas H/He sebelum gas itu ditiup angin T Tauri.</p>` },
  { h: 'Merkurius dan Venus', body: R`<p><b>Merkurius</b>: elongasi maksimum hanya ~18°–28° (orbitnya lonjong, e = 0,21), sehingga selalu rendah di senja/fajar. Atmosfer hampir tidak ada: gravitasi kecil dan suhu tinggi membuat kecepatan termal gas mendekati kecepatan lepas, dan angin surya menyapu sisanya; maka siang 430 °C, malam −180 °C. Permukaan penuh kawah seperti Bulan, tetapi kerapatan 5,4 g/cm³ (inti besi raksasa). Rotasinya beresonansi <b>3 : 2</b> (58,65 hari) dengan revolusi (87,97 hari), sehingga satu hari matahari = 176 hari = 2 tahun Merkurius. Periode rotasi ini ditemukan dengan Doppler radar (1965). Perihelionnya bergeser 574″ per abad: 531″ akibat planet lain dan <b>43″ sisanya dijelaskan relativitas umum</b> Einstein (bukan planet "Vulcan").</p><p><b>Venus</b>: benda terterang setelah Matahari dan Bulan, elongasi maks ~46° (bintang fajar/senja). Atmosfer 96% CO₂ dengan tekanan ~92 bar dan awan asam sulfat yang korosif; efek rumah kaca yang "lepas kendali" membuat permukaan ~460 °C, siang dan malam hampir sama. Rotasinya retrograd 243 hari, permukaan dipetakan dengan radar (Magellan): ~65% dataran bergelombang, vulkanik, kawah sedikit dan hanya yang besar (meteoroid kecil terbakar habis di atmosfer tebal). Venus menunjukkan fase lengkap (bukti heliosentrik Galileo); tampak paling besar saat sabit, paling kecil saat hampir purnama, paling terang saat sabit lebar (elongasi ~39°). Transit Venus (2004, 2012; berikutnya 2117) dulu dipakai untuk mengukur satuan astronomi lewat paralaks.</p>`, lab: 'planetdalam' },
  { h: 'Bumi sebagai planet', body: R`<p>Bukti Bumi bulat: kapal menghilang dari lambung dulu, bayangan bundar Bumi saat gerhana Bulan, bintang kutub makin tinggi ke utara, foto dari angkasa, dan metode <b>Eratosthenes</b> (sudut 1/50 lingkaran antara Syene dan Alexandria yang terpisah 5000 stadia → keliling 250 000 stadia ≈ 40 000 km). Rotasi membuat Bumi pepat (kepepatan 1/298) dan g di kutub (9,832) lebih besar daripada di ekuator (9,780). Massa dari \(M = gR^2/G = 6{,}0\times10^{24}\) kg.</p><p>Bukti rotasi: <b>bandul Foucault</b> (1851; bidang ayun berputar 360° sin φ per hari sideris) dan <b>efek Coriolis</b> (benda yang bergerak di permukaan berbelok ke kanan di belahan utara, ke kiri di selatan, sehingga siklon berputar berlawanan jarum jam di utara). Bukti revolusi: <b>paralaks</b> bintang, <b>aberasi</b> cahaya bintang (20,5″ = v/c), dan pergeseran Doppler tahunan bintang di dekat ekliptika (±30 km/s). Hari sideris 23 j 56 m 4 d; hari matahari 24 j karena Bumi harus berputar ~1° lagi untuk menghadap Matahari.</p>`, lab: 'harisurya' },
  { h: 'Bulan', body: R`<p>Diameter 3476 km, massa 1/81 M⊕, g permukaan 1/6. Rotasi sinkron (27,32 hari) akibat pengereman pasang surut, sehingga wajahnya tetap. Gesekan pasang surut juga memperlambat rotasi Bumi (~2 ms per abad) dan memindahkan momentum sudut ke Bulan sehingga Bulan menjauh ~3,8 cm per tahun. <b>Terrae</b> (dataran tinggi terang, ~83%) penuh kawah dan berumur ~4,4 miliar tahun; <b>maria</b> (~17%) adalah cekungan tumbukan raksasa yang terisi lava basalt 3,1–3,9 miliar tahun lalu, jadi lebih muda dan kawahnya lebih sedikit. Pembentukan Bulan: <b>tumbukan raksasa</b> (Hartmann–Davis 1975; Canup) antara proto-Bumi dan benda seukuran Mars (Theia): menjelaskan Bulan miskin besi (yang terlontar sebagian besar mantel), kerapatan 3,3 g/cm³, isotop oksigen sama dengan Bumi, dan momentum sudut besar sistem Bumi–Bulan. Pasang surut dan fase dibahas di Bab 6, gerhana di Bab 13.</p>` },
  { h: 'Mars dan "zona layak huni"', body: R`<p>Mars: diameter setengah Bumi, massa 0,11 M⊕, hari 24 j 37 m, kemiringan sumbu 25° (bermusim), dua satelit kecil tak bulat (Phobos 27 km, Deimos 15 km, gravitasinya terlalu lemah untuk membulatkan diri). Atmosfer 95% CO₂ tetapi hanya ~0,6% tekanan Bumi, sehingga efek rumah kaca kecil (~5 K) dan air cair tidak stabil. Mars kecil → cepat mendingin → inti membeku, medan magnet global hilang, vulkanisme berhenti (Olympus Mons 22 km, gunung tertinggi di tata surya, karena tidak ada lempeng yang bergerak: magma terus menumpuk di titik yang sama), angin surya mengikis atmosfer, CO₂ terkunci di batuan dan tudung kutub ("runaway refrigerator"). Jejak air purba: saluran sungai, delta, mineral lempung; es air kini di tudung kutub dan di bawah permukaan.</p><p>Empat proses geologi membentuk permukaan planet terestrial: vulkanisme, tektonisme, erosi, dan kawah tumbukan. Planet kecil (Bulan, Merkurius) mendingin cepat sehingga hanya kawah yang tersisa; Bumi yang besar masih aktif sehingga kawahnya cepat terhapus.</p>`, lab: 'zonaair' },
  { h: 'Planet-planet Jovian', body: R`<p><b>Jupiter</b> (318 M⊕, rotasi ~10 jam): 90% H dan 10% He seperti nebula asal; di bawah awan, H menjadi cair lalu <b>hidrogen metalik</b> (tekanan jutaan bar) yang menghasilkan medan magnet terkuat dan magnetosfer terbesar; inti batuan-es ~10–15 M⊕. Ia memancarkan ~1,7× energi yang diterimanya dari Matahari (panas sisa pengerutan), tetapi ~80× terlalu ringan untuk fusi hidrogen, maka julukan "bintang gagal". Pita terang (zone) dan gelap (belt) adalah aliran naik-turun yang diregangkan rotasi cepat (Coriolis); Bintik Merah Besar adalah badai antisiklon yang bertahan ratusan tahun karena tak ada daratan yang meredam energinya. Satelit Galileo: Io (vulkanik, dipanasi pasang surut karena orbitnya dibuat eksentrik oleh resonansi 1 : 2 : 4 dengan Europa dan Ganymede), Europa (lautan di bawah es), Ganymede (satelit terbesar, lebih besar dari Merkurius), Callisto (paling berkawah, permukaan tertua). Satelit kecil terluar banyak yang retrograd: asteroid yang tertangkap.</p><p><b>Saturnus</b> (kerapatan 0,69 g/cm³ < air, paling pepat): cincin es yang tipis (puluhan meter) di dalam <b>limit Roche</b>; menghilang saat dilihat dari sisi tepi (dua kali tiap 29,5 tahun; terakhir 2025). Partikel cincin mengikuti hukum Kepler (bagian dalam lebih cepat). Titan: satu-satunya satelit beratmosfer tebal (N₂, 1,5 bar) dengan danau metana. <b>Uranus</b> dan <b>Neptunus</b> adalah "raksasa es": inti batuan dan mantel air–amonia–metana yang lebih besar, selubung H/He tipis; warna biru karena metana menyerap merah. Sumbu rotasi Uranus miring 98° (musim ekstrem) dan medan magnet keduanya miring dan tak berpusat. Cincin Uranus ditemukan 1977 lewat <b>okultasi bintang</b> (bintang berkedip beberapa kali, simetris di kedua sisi planet). Neptunus ditemukan 1846 dari gangguan orbit Uranus (Adams dan Le Verrier); satelitnya Triton (2707 km) mengorbit retrograd, kemungkinan objek Kuiper yang tertangkap.</p>`, lab: 'roche' },
  { h: 'Asteroid, komet, meteoroid', body: R`<p><b>Asteroid</b>: sebagian besar di sabuk utama 2,1–3,3 SA. Celah <b>Kirkwood</b> berada di jarak resonansi dengan Jupiter (periode 1/3, 2/5, 3/7, 1/2 periode Jupiter; \(a = 5{,}20\,(P/P_J)^{2/3}\)), tempat gangguan Jupiter yang berulang menumpuk dan melempar asteroid keluar, sebagian menjadi asteroid dekat Bumi. Tipe spektrum C (karbon), S (silikat), M (logam), sama dengan jenis meteorit. Asteroid kecil sering "tumpukan puing" (rubble pile).</p><p><b>Komet</b>: inti es-debu ~1–50 km, orbit sangat lonjong. Dekat Matahari (< ~3 SA) es menyublim membentuk <b>koma</b>, awan hidrogen, dan dua <b>ekor</b>: ekor ion/plasma (biru, lurus, didorong angin surya tepat menjauhi Matahari, panjang ~1 SA) dan ekor debu (kekuningan, melengkung, didorong tekanan radiasi). Periode pendek (< 200 tahun) berasal dari <b>sabuk Kuiper</b> (30–50 SA, dekat bidang ekliptika); periode panjang dari <b>awan Oort</b> (bola ~2000–100 000 SA berisi ~10¹² komet). Parameter Tisserand \(T = a_J/a + 2\sqrt{(a/a_J)(1-e^2)}\cos i\) membedakan komet ekliptik (T > 2) dan isotropik (T < 2).</p><p><b>Meteoroid</b> = batu kecil di ruang antarplanet; <b>meteor</b> = jejak cahaya saat ia terbakar di ketinggian 80–110 km; <b>meteorit</b> = sisa yang sampai di tanah. Hujan meteor terjadi saat Bumi melintasi orbit puing komet (Perseid–Swift-Tuttle, Leonid–Tempel-Tuttle; Geminid berasal dari asteroid Phaethon). Lebih banyak meteor setelah tengah malam, karena saat itu kita di sisi depan Bumi yang "menabrak" meteoroid. Meteorit berumur 4,56 miliar tahun: fosil awal tata surya.</p>`, lab: 'komet' },
  { h: 'Pembentukan tata surya dan status Pluto', body: R`<p>Fakta yang harus dijelaskan teori: semua planet beredar searah dan hampir sebidang; orbit hampir lingkaran; Matahari memuat 99,86% massa tetapi hanya ~2% momentum sudut; dua kelompok planet; umur ~4,6 miliar tahun.</p><ul><li><b>Nebula Kant–Laplace</b> (1755/1796; buku keliru menulis 1976): awan berputar mengerut menjadi cakram, cincin-cincin menjadi planet. Menjelaskan arah dan bidang orbit, tetapi gagal pada momentum sudut (Matahari seharusnya berputar sangat cepat) dan cincin gas sulit menggumpal.</li><li><b>Pasang surut / planetesimal</b> (Chamberlin–Moulton 1900, Jeans–Jeffreys) dan <b>tumbukan</b> (Jeffreys; bintang pasangan, Russell–Lyttleton): materi planet ditarik dari Matahari oleh bintang yang lewat. Gagal: gas panas yang tercabut akan menyebar, bukan menggumpal; momentum sudut tetap bermasalah; dan perjumpaan bintang sangat jarang.</li><li><b>Turbulensi</b> (von Weizsäcker 1945) dan <b>protoplanet</b> (Kuiper 1950): cakram turbulen, gumpalan tumbuh menjadi protoplanet, angin surya menyapu gas ringan.</li></ul><p>Teori modern adalah turunan teori nebula: <b>cakram protoplanet</b> → debu menggumpal → planetesimal → embrio planet; momentum sudut Matahari dibuang oleh medan magnet dan angin bintang (rem magnetik). Cakram serupa kini terlihat langsung di sekitar bintang muda (ALMA), dan ribuan eksoplanet telah ditemukan.</p><p><b>IAU 2006</b>: planet adalah benda yang (1) mengorbit Matahari, (2) cukup masif sehingga bulat (setimbang hidrostatik), dan (3) telah "membersihkan" lingkungan orbitnya. Pluto gagal syarat 3 (ia salah satu dari banyak objek sabuk Kuiper dan orbitnya bersilangan dengan Neptunus), sehingga menjadi <b>planet kerdil</b> bersama Ceres, Eris (dulu dijuluki "Xena"), Haumea, dan Makemake. Charon bukan planet kerdil; ia satelit Pluto (pusat massa sistem berada di luar Pluto). New Horizons melintasi Pluto pada Juli 2015.</p>` }
 ],
 groups: [
  { name: 'Review', items: [
   E('R1', R`Jelaskan dan gambarkan struktur dalam Matahari beserta keterangan tiap lapisan.`, R`Inti (0–0,25 R☉, ~15 juta K, fusi), zona radiatif (0,25–0,71 R☉, energi dibawa radiasi), zona konveksi (0,71–1 R☉, energi dibawa aliran gas); di atasnya fotosfer, kromosfer, korona.`, R`Lihat gambar struktur Matahari di materi. Kerapatan pusat ~150 g/cm³, turun drastis ke luar; separuh massa berada di dalam 0,25 R☉.`),
   E('R2', R`Perbedaan planet Jovian dan terestrial.`, R`Lihat tabel di materi: ukuran, kerapatan, komposisi, atmosfer, rotasi, satelit, cincin, panas dalam.`, R`Penyebab mendasar: garis salju di cakram protoplanet. Di luar garis salju es ikut mengembun, inti tumbuh besar dan sempat menarik gas H/He.`),
   E('R3', R`Teori pembentukan tata surya beserta kelebihan dan kekurangannya.`, R`Lihat topik "Pembentukan tata surya": nebula (arah/bidang orbit benar, momentum sudut salah), pasang surut/tumbukan (mencoba memecahkan momentum sudut, tetapi gas panas menyebar dan perjumpaan bintang terlalu jarang), turbulensi dan protoplanet (dasar teori modern).`, R`Teori modern = nebula + cakram protoplanet + akresi planetesimal + rem magnetik.`),
   E('R4', R`Mengapa Pluto dikeluarkan dari kategori planet (Agustus 2006)?`, R`Ia tidak memenuhi syarat ketiga definisi IAU: belum membersihkan lingkungan orbitnya. Pluto hanyalah salah satu objek besar di sabuk Kuiper (Eris bahkan sedikit lebih masif) dan orbitnya bersilangan dengan Neptunus.`, R`Massanya hanya 0,002 M⊕ (≈ 0,07 kali total massa objek di zona orbitnya), sedangkan planet sejati mendominasi zonanya ribuan kali.`),
   E('R5', R`Ciri khas tiap planet.`, R`Merkurius: resonansi 3:2, inti besi besar, kawah. Venus: retrograd, rumah kaca ekstrem 460 °C. Bumi: air cair, lempeng tektonik, oksigen, kehidupan. Mars: merah (oksida besi), Olympus Mons, tudung kutub. Jupiter: terbesar, Bintik Merah, hidrogen metalik. Saturnus: cincin terang, kerapatan < air. Uranus: sumbu miring 98°. Neptunus: angin tercepat (~2000 km/jam), ditemukan lewat perhitungan.`, R`Rincian di topik-topik materi.`),
   E('R6', R`Teori pembentukan Bulan.`, R`Yang paling diterima: tumbukan raksasa proto-Bumi dengan benda seukuran Mars ~4,5 miliar tahun lalu; puing mantel membentuk cakram yang menggumpal menjadi Bulan.`, R`Teori lama: pembelahan (fission, Bumi berotasi terlalu cepat), penangkapan (capture), dan terbentuk bersama (co-accretion). Ketiganya gagal menjelaskan sekaligus miskin besi, isotop yang sama dengan Bumi, dan momentum sudut sistem.`),
   E('R7', R`Bumi dan Venus "kembar" tetapi sangat berbeda. Apa saja bedanya dan mengapa?`, R`Ukuran, massa, kerapatan mirip; tetapi Venus: atmosfer CO₂ 92 bar, 460 °C, tanpa air, awan H₂SO₄, rotasi retrograd 243 hari, tanpa medan magnet dan tanpa satelit, tanpa lempeng tektonik aktif. Penyebab utama: Venus lebih dekat Matahari → air tidak pernah bisa (atau tidak lama) mengembun menjadi lautan → CO₂ tidak larut dan tidak terkunci menjadi batu karbonat → rumah kaca lepas kendali; uap air terurai UV dan hidrogen lolos ke angkasa.`, R`Di Bumi CO₂ yang setara dengan atmosfer Venus tersimpan dalam batu kapur.`),
   E('R8', R`Mengapa perihelion Merkurius bergeser? Hubungan Matahari dan ketiadaan atmosfer Merkurius?`, R`Pergeseran 574″/abad: 531″ akibat gangguan planet lain, 43″ akibat kelengkungan ruang-waktu di dekat Matahari (relativitas umum). Atmosfer: suhu tinggi (dekat Matahari) membuat molekul cepat, gravitasi kecil membuat kecepatan lepas rendah (4,3 km/s), dan angin surya menyapu gas.`, R`Atmosfer "eksosfer" Merkurius yang sangat tipis berisi atom yang terus dipasok angin surya dan pemercikan permukaan.`),
   E('R9', R`Mengapa Jupiter disebut "bintang gagal"?`, R`Komposisinya seperti bintang (H, He) dan ia memancarkan lebih banyak energi daripada yang diterima, tetapi massanya (0,001 M☉) ~80× terlalu kecil untuk membuat inti cukup panas dan rapat bagi fusi hidrogen (batas ~0,08 M☉).`, R`Bahkan katai cokelat (13–80 M_J) hanya membakar deuterium sebentar.`),
   E('R10', R`Apa itu objek sabuk Kuiper dan awan Oort?`, R`Sabuk Kuiper: cakram benda es di luar Neptunus (30–50 SA), sumber komet periode pendek; Pluto, Eris, Makemake termasuk. Awan Oort: kulit bola raksasa (~2000–100 000 SA) berisi triliunan inti komet, sumber komet periode panjang yang datang dari segala arah.`, R`Awan Oort hanya hipotesis (Oort 1950) yang disimpulkan dari orbit komet baru, belum teramati langsung.`)
  ] },
  { name: 'Esai (1–25)', items: [
   E('E1', R`(a) Mengapa terjadi flare? (b) Mengapa flare teramati di korona, kromosfer, dan fotosfer? (c) Perlukah sistem peringatan dini flare?`, R`(a) Garis medan magnet di daerah aktif terpelintir dan tertekan oleh gerak fotosfer; bila menyambung ulang (rekoneksi), energi magnet dilepas mendadak (hingga 10²⁵ J dalam menit). (b) Energi dilepas di korona; elektron dan proton yang dipercepat menuruni garis medan memanaskan kromosfer (flare Hα) dan pada flare besar sampai fotosfer (flare cahaya putih), sehingga satu peristiwa tampak di semua lapisan dan semua panjang gelombang. (c) Perlu: sinar-X dan partikel energetik mengganggu radio HF, GPS, satelit, astronot, dan penerbangan kutub; CME yang menyertai bisa merusak jaringan listrik.`, R`Peringatan dini memanfaatkan pemantauan daerah aktif (SDO, satelit GOES) dan selang waktu: sinar-X tiba 8 menit, partikel puluhan menit, CME 1–4 hari.`),
   E('E2', R`Mengapa fenomena alam semesta perlu dianalisis dengan teleskop radio, optik, dan sinar-X?`, R`Tiap panjang gelombang menunjukkan proses dan suhu berbeda: sinar-X → gas jutaan K (korona, gugus galaksi, piringan akresi); optik → bintang dan gas ~10⁴ K; radio → gas dingin (garis 21 cm HI, molekul), elektron di medan magnet (sinkrotron), dan menembus debu. Gambaran lengkap butuh semuanya.`, R`Hukum Wien: λ_maks ∝ 1/T, jadi objek panas dan dingin "bersinar" di jendela yang berbeda.`),
   E('E3', R`Mengapa astronom menyimpulkan Matahari adalah bintang? Buktinya?`, R`Spektrumnya sejenis dengan spektrum bintang (kelas G2: garis serapan yang sama); bila Matahari dipindah ke jarak bintang (mis. 10 pc) magnitudonya 4,8, sama seperti bintang biasa di deret utama; massa, radius, suhu, luminositasnya terletak di deret utama diagram H–R.`, R`Sebaliknya bintang adalah "matahari jauh": Bessel (1838) menunjukkan dengan paralaks bahwa bintang-bintang sangat jauh, sehingga cahayanya yang lemah setara dengan Matahari.`),
   E('E4', R`Proses pembangkitan energi di inti Matahari.`, R`Fusi rantai proton–proton (~99%): p + p → d + e⁺ + ν; d + p → ³He + γ; ³He + ³He → ⁴He + 2p. Hasil bersih 4 ¹H → ⁴He + 2e⁺ + 2ν + 26,7 MeV (0,7% massa). Daur CNO menyumbang ~1%.`, R`Rinci di Bab 8 (lab puncak Gamow). Langkah p + p sangat lambat (gaya lemah), itulah sebabnya Matahari berumur panjang.`),
   E('E5', R`Apa yang dimaksud rotasi diferensial Matahari?`, R`Laju rotasi bergantung lintang (dan kedalaman): ekuator ~25 hari, lintang tinggi ~35 hari, karena Matahari adalah bola gas, bukan benda tegar.`, R`Helioseismologi menunjukkan perbedaan ini menembus seluruh zona konveksi; zona radiatif berotasi hampir tegar. Lapisan geser di antaranya (tachocline) diduga tempat dinamo bekerja. Lihat lab dinamo.`),
   E('E6', R`Periode rata-rata siklus bintik dan cara mengenali awal siklus.`, R`~11 tahun (bervariasi 9–14). Awal siklus ditandai bintik-bintik di lintang tinggi (±25°–35°) yang polaritas pendahulunya berlawanan dengan siklus sebelumnya, muncul saat bintik siklus lama masih ada di dekat ekuator.`, R`Lihat lab diagram kupu-kupu.`),
   E('E7', R`(a) Apakah frekuensi ledakan (flare) berkorelasi dengan siklus bintik? (b) Flare teramati di filter Hα 6563 Å: di lapisan mana? (c) Teramati di sinar-X: di lapisan mana?`, R`(a) Ya: flare berasal dari daerah aktif bermedan kuat, yang paling banyak saat siklus maksimum. (b) Kromosfer. (c) Korona (plasma jutaan K).`, R`Flare besar tetap bisa terjadi di fase menurun siklus.`),
   E('E8', R`Mengapa bintik dan tepi piringan Matahari tampak terang di sinar-X tetapi gelap secara visual?`, R`Secara visual kita melihat fotosfer: bintik lebih dingin, tepi menunjukkan lapisan atas yang lebih dingin (penggelapan tepi). Di sinar-X fotosfer (5800 K) praktis tidak memancar; yang terlihat korona panas. Di atas bintik ada busur korona yang panas dan rapat; di tepi piringan garis pandang menembus kolom korona yang lebih panjang (pencerahan tepi).`, R`Jadi yang "terang" di sinar-X bukan bintiknya sendiri, melainkan korona di atasnya.`),
   E('E9', R`L☉ = 3,86 × 10²⁶ W. Hitung laju pengurangan massa Matahari dan persentase pengurangan selama ~5 miliar tahun (M☉ = 1,99 × 10³⁰ kg).`, R`4,3 × 10⁹ kg/s; total 6,8 × 10²⁶ kg ≈ 0,034% massa Matahari.`, R`\(\dot M = L/c^2 = 3{,}86\times10^{26}/(3\times10^8)^2 = 4{,}29\times10^9\) kg/s. Dikali 5 × 10⁹ × 3,156 × 10⁷ s = 1,58 × 10¹⁷ s → 6,78 × 10²⁶ kg; dibagi 1,99 × 10³⁰ → 3,4 × 10⁻⁴.`, 'Angin surya menambah ~1,5 × 10⁹ kg/s lagi, tetap kecil.'),
   E('E10', R`Jelaskan efek penggelapan tepi.`, R`Kita melihat sampai kedalaman optik ~1 di sepanjang garis pandang. Di pusat piringan garis pandang tegak lurus sehingga menembus lapisan lebih dalam dan panas; di tepi garis pandang miring sehingga kedalaman optik 1 dicapai di lapisan lebih tinggi dan dingin. Lebih dingin = lebih redup (Stefan–Boltzmann) dan lebih merah.`, R`Intensitas tepi kira-kira 40–50% pusat di cahaya visual. Efek ini juga bukti suhu fotosfer menurun ke atas.`),
   E('E11', R`Mengapa kromosfer paling baik dilihat di garis emisi Hα 656,3 nm?`, R`Kromosfer sangat redup di kontinum dibanding fotosfer, tetapi gas hidrogennya yang panas dan renggang memancarkan kuat di garis Hα, tepat di panjang gelombang tempat fotosfer menyerap (garis gelap). Filter Hα sempit (< 1 Å) menahan cahaya fotosfer sehingga kromosfer menonjol.`, R`Hα adalah transisi n = 3 → 2 (deret Balmer); warnanya merah, sehingga kromosfer tampak "berwarna" (chroma) saat gerhana.`),
   E('E12', R`Mengapa kromosfer dan korona hanya teramati saat gerhana Matahari?`, R`Kecerlangannya ~10⁻⁴ (kromosfer) dan ~10⁻⁶ (korona) kali fotosfer, sehingga tenggelam dalam silau fotosfer dan cahaya langit yang terhambur. Saat gerhana total Bulan menutup tepat fotosfer.`, R`Kini juga bisa dengan koronagraf (gerhana buatan, terbaik di angkasa: SOHO/LASCO), filter Hα, dan teleskop EUV/sinar-X.`),
   E('E13', R`Hitung bilangan Wolf penampakan bintik 4 Juli 2000 (tabel daftar kelompok NOAA: NMBR, LOCATI, Lo, AREA, Z, LL, NN, MAG TYPE).`, R`R = 10g + f (dengan k = 1): hitung jumlah baris kelompok g dan jumlahkan kolom jumlah bintik f.`, R`Contoh: bila tabel memuat 8 kelompok dengan total 60 bintik, R = 10 × 8 + 60 = 140. Kolom LL dan Z tidak dipakai. Data NOAA tanggal itu (dekat maksimum siklus 23) memang berada di kisaran R ~ 150–200.`, 'Tabel data soal ini tidak tercetak di diktat, sehingga angka pastinya tidak bisa dihitung; yang diuji adalah cara memakai rumus.'),
   E('E14', R`Ciri dan fenomena tiap lapisan Matahari: inti, fotosfer, kromosfer, korona, heliosfer.`, R`Inti: 15 juta K, rapat, fusi, sumber neutrino. Fotosfer: 5800 K, permukaan tampak, granulasi, bintik, fakula, penggelapan tepi, garis Fraunhofer. Kromosfer: 4000 → 10⁴ K, Hα merah, spikula, plage, filamen, flare Hα. Korona: 1–2 juta K, sangat renggang, busur korona, lubang korona, CME, garis Fe XIV. Heliosfer: gelembung angin surya sampai heliopause (~120 SA) tempat bertemu medium antarbintang.`, R`Voyager 1 melewati heliopause tahun 2012.`),
   E('E15', R`Bagaimana astronom tahu bintik adalah pemusatan medan magnet? Apa siklus magnetik Matahari?`, R`Dari efek Zeeman (Hale 1908): garis spektrum di bintik terpecah dan komponennya terpolarisasi, jarak pecahan sebanding kuat medan (~0,3 T). Siklus magnetik: polaritas bintik pendahulu di tiap belahan dan medan kutub berbalik tiap 11 tahun, sehingga keadaan magnet kembali sama setelah 22 tahun.`, R`Gambarannya ada di lab kupu-kupu (titik merah/biru di piringan berbalik tiap siklus).`),
   E('E16', R`Venus berfase seperti Bulan tetapi tidak pernah tampak purnama. Mengapa?`, R`Venus purnama hanya saat konjungsi superior: Venus tepat di belakang Matahari, tenggelam dalam silau (atau tertutup piringan Matahari).`, R`Di dekat konjungsi superior Venus tampak hampir bulat tetapi kecil. Geser θ mendekati 180° di lab planet dalam.`),
   E('E17', R`Tabel efemeris Merkurius dan Venus 7–11 November (asensio rekta dan deklinasi). Peristiwa apa yang terjadi, kapan, dan mengapa?`, R`(1) Konjungsi Merkurius–Venus (sama asensio rektanya) sekitar 8 November pukul ~20 (jam efemeris), terpisah ~2° (Merkurius di selatan). (2) Merkurius berhenti (stasioner) sekitar 9,8 November lalu mulai bergerak mundur (retrograd).`, R`Selisih α Merkurius − Venus: 8 Nov +3 m 41 s, 9 Nov −48 s → nol pada 8 Nov + 221/269 hari = 8 Nov ~19,7 jam. Deklinasi saat itu: Merkurius −23°42′, Venus −21°38′. Pertambahan α harian Merkurius: +77, +45, +10, −28 detik → pertambahan nol sekitar 9,8 November: Merkurius stasioner (menjelang konjungsi inferior), sedangkan Venus terus maju ~5 m 14 s/hari.`, 'Deklinasi Venus 11 Nov di tabel (−21°10′38″) tampaknya salah ketik −22°10′38″ (urutannya terus turun ~15′ per hari).'),
   E('E18', R`Asteroid 400 m membuat kawah berdiameter 10 km di Bulan setiap 10 juta tahun. (a) Berapa lama sampai seluruh muka Bulan tertutup kawah seukuran itu? (b) Berapa kali lebih cepat laju pembentukan kawah dulu agar seluruh permukaan tertutup dalam 4,6 miliar tahun?`, R`(a) ~4,8 × 10¹² tahun (4,8 triliun tahun). (b) ~1000 kali lebih cepat.`, R`Luas Bulan 4π(1737 km)² = 3,79 × 10⁷ km²; luas satu kawah π(5 km)² = 78,5 km² → 4,8 × 10⁵ kawah × 10⁷ tahun. (b) 4,83 × 10¹²/4,6 × 10⁹ = 1050. Kenyataan bahwa dataran tinggi Bulan jenuh kawah menunjukkan tumbukan dulu jauh lebih sering ("pengeboman berat" ~4 miliar tahun lalu).`),
   E('E19', R`Mars (6,4 × 10²³ kg) menabrak Bumi (6,0 × 10²⁴ kg) dengan laju sama dengan laju orbit Bumi. Melelehkan batuan butuh 10⁶ J/kg. Tunjukkan energinya cukup untuk melontarkan materi sebesar Bulan (7,4 × 10²² kg) ke angkasa. R⊕ = 6500 km.`, R`Energi kinetik ~2,8 × 10³² J, ~47× energi untuk melelehkan seluruh Bumi (6 × 10³⁰ J) dan ~60× energi untuk mengangkat massa Bulan keluar dari sumur gravitasi Bumi (~4,6 × 10³⁰ J). Jadi sangat cukup.`, R`\(E_k = \tfrac12(6{,}4\times10^{23})(2{,}98\times10^4)^2 = 2{,}84\times10^{32}\) J. Energi lepas massa Bulan: \(GM_\oplus m/R = 6{,}67\times10^{-11}\cdot6\times10^{24}\cdot7{,}4\times10^{22}/6{,}5\times10^6 = 4{,}6\times10^{30}\) J. Inilah inti teori tumbukan raksasa.`, 'Soal menganggap kecepatan relatif tabrakan sebesar laju orbit Bumi (29,8 km/s). Dalam model modern laju tumbukan Theia jauh lebih kecil (~4 km/s, sedikit di atas kecepatan lepas), dan energinya (~10³¹ J) tetap cukup.'),
   E('E20', R`Tabel diameter, massa, gravitasi, kerapatan planet, serta persentase pasangan bahan (Batuan+Logam dan pasangan kedua) yang menghasilkan kerapatan tiap planet. (a) Kecocokan tiap planet; (b) planet mana yang tidak memenuhi syarat pasangan apa pun? (c) Terbuat dari apa? (d) Planet mana yang keadaannya hampir serupa?`, R`Dari angka Bumi dan Mars, kerapatan yang dipakai tabel: batuan ≈ 3,5, logam ≈ 8,0, gas-es-cair ≈ 0,94 g/cm³; pasangan kedua ternyata Logam + Gas/Es/Cair. (a) Pasangan Batuan+Logam (nilai 0–1) hanya cocok untuk Bumi, Venus, Merkurius, Mars (dan Bulan hampir: −0,03 ≈ batuan murni); Jupiter, Uranus, Neptunus, Pluto hanya cocok dengan pasangan kedua. (b) Saturnus: kedua pasangan memberi nilai negatif (1,64/−0,64 dan −0,04/1,04), karena kerapatannya (0,62) lebih kecil dari bahan teringan pun. (c) Saturnus terutama hidrogen dan helium (gas/cair bertekanan), lebih ringan dari air. (d) Jupiter dan Uranus (1,24/1,25, persentase identik); Merkurius, Venus, Bumi mirip; Neptunus dan Pluto mendekati.`, R`Selesaikan sistem: 0,55ρ_b + 0,45ρ_l = 5,52 dan 0,91ρ_b + 0,09ρ_l = 3,90 → ρ_b = 3,50, ρ_l = 8,00. Pasangan kedua: 0,65ρ_l + 0,35ρ_g = 5,52 → ρ_g = 0,94. Cek Saturnus: −0,04(8) + 1,04(0,94) = 0,66 ≈ 0,62 → butuh fraksi "gas" > 1.`, 'Judul kolom tabel pasangan kedua tertulis "Batuan, GasEsCr", padahal hitungannya hanya cocok bila kolom itu Logam + GasEsCair. Kerapatan rata-rata belum dikoreksi pemampatan: Bumi tanpa tekanan sebenarnya ~4,4 g/cm³, jadi ini hanya model kasar.'),
   E('E21', R`Saat Matahari terbenam Venus berelongasi 30°. Jarak Venus dan Bumi ke Matahari 108,2 dan 149,6 juta km. Berapa jarak Venus dari Bumi? Berapa sudut antara Bumi dan Venus dilihat dari Matahari?`, R`Dua kemungkinan: 51,4 juta km (Venus di sisi dekat, sabit; sudut di Matahari 13,7°) atau 207,7 juta km (di sisi jauh, cembung; sudut di Matahari 106,3°).`, R`Aturan kosinus: 108,2² = d² + 149,6² − 2(149,6)d cos 30° → d² − 259,1d + 10 673 = 0 → d = 51,4 atau 207,7. Sudut di Matahari dari cos S = (149,6² + 108,2² − d²)/(2·149,6·108,2). Coba preset "Soal 21" di lab planet dalam.`, 'Soal menulis "antara Bumi dan Mars"; yang dimaksud tentu Bumi dan Venus.'),
   E('E22', R`Merkurius dan Venus dipotret bersamaan di elongasi terbesarnya (28° dan 46°). Bagaimana bentuk citranya? Mana yang lebih dekat ke Bumi?`, R`Keduanya tampak setengah (dikotomi, sudut fase 90°), sisi terang menghadap Matahari di barat. Venus lebih dekat: 0,69 SA, Merkurius 0,88 SA; jadi Venus tampak jauh lebih besar (~25″ vs ~8″) dan terang.`, R`Pada elongasi terbesar garis pandang menyinggung orbit → segitiga siku-siku di planet: d = cos(elongasi) SA. cos 46° = 0,695; cos 28° = 0,883.`),
   E('E23', R`Garis Matahari–Venus dan Matahari–Merkurius masing-masing tegak lurus garis Matahari–Bumi. Mana yang lebih dekat ke Bumi?`, R`Merkurius: √(1 + 0,387²) = 1,07 SA, Venus: √(1 + 0,723²) = 1,23 SA.`, R`Siku-siku di Matahari, jadi d² = 1 + r². Planet yang lebih dekat ke Matahari lebih dekat ke Bumi pada konfigurasi ini.`),
   E('E24', R`Mengapa Venus tampak terbesar saat sabit, terkecil saat (hampir) purnama, dan paling terang saat "setengah"?`, R`Ukuran sudut ∝ 1/jarak: sabit terjadi saat Venus di sisi dekat (0,28 SA), hampir purnama saat di sisi jauh (1,72 SA). Kecerlangan ∝ (bagian terang)/jarak²: kompromi antara keduanya mencapai maksimum saat sabit lebar (~27% terang, elongasi ~39°, ~36 hari sebelum/sesudah konjungsi inferior).`, R`Buku menyebut "setengah"; perhitungan memberi sabit lebar. Lihat keluaran kecerlangan di lab planet dalam.`),
   E('E25', R`Bagaimana menentukan jarak Bumi–Matahari dari transit Venus?`, R`Dua pengamat yang jauh terpisah di Bumi melihat Venus melintasi piringan Matahari pada tali busur yang sedikit berbeda (paralaks). Dari beda lintasan (atau beda waktu kontak) diperoleh paralaks Venus relatif Matahari; karena rasio jarak Venus dan Bumi dari Matahari diketahui dari hukum Kepler III (0,723), paralaks itu dapat diubah menjadi jarak absolut dalam km, lalu SA.`, R`Paralaks relatif = paralaks Matahari × (1/0,277 − 1) ≈ 2,6 kali paralaks Matahari, sehingga lebih mudah diukur. Halley mengusulkan metode ini; ekspedisi transit 1761/1769 (termasuk Cook di Tahiti) memberi SA ~150 juta km.`),
  ] },
  { name: 'Esai (26–50)', items: [
   E('E26', R`Gambarkan posisi Bumi, Matahari, Venus ketika Venus menjadi "bintang pagi" dan "bintang sore".`, R`Dilihat dari kutub utara (orbit berlawanan jarum jam), dari Bumi menghadap Matahari: Venus di kanan garis Bumi–Matahari = di barat Matahari = terbit sebelum Matahari (bintang pagi, sesudah konjungsi inferior); di kiri = timur Matahari = terbenam sesudah Matahari (bintang sore, sebelum konjungsi inferior).`, R`Lab planet dalam menuliskan "tampak pagi/sore" sesuai posisi. Sesudah konjungsi inferior Venus "menyalip" Bumi dan muncul di langit pagi.`),
   E('E27', R`Planet fiktif berotasi (berlawanan jarum jam) sekali dalam 2000 jam dan beredar (juga berlawanan jarum jam) sekali dalam 6000 jam. Tunjukkan dengan diagram bahwa hari mataharinya 3000 jam.`, R`Dalam 3000 jam planet berotasi 1,5 kali, sementara ia berpindah setengah orbit (180°). Titik yang semula menghadap Matahari, setelah 1,5 putaran menghadap arah sebaliknya dari arah semula, padahal Matahari kini juga ada di arah sebaliknya (planet di sisi lain orbit) → tengah hari lagi. Jadi hari matahari 3000 jam.`, R`Cek rumus: 1/S = 1/2000 − 1/6000 = 1/3000. Preset "Soal 27" di lab hari sideris/matahari menampilkan diagramnya: geser waktu dari 0 ke 1.`),
   E('E28', R`Mengapa kawah kecil sangat sedikit di Venus tetapi sangat banyak di Bulan? Mengapa udara Venus korosif?`, R`Atmosfer Venus yang 92 bar memperlambat, memanaskan, dan menghancurkan meteoroid kecil (< ~1 km) sebelum menyentuh tanah; permukaannya juga relatif muda (~0,5–0,7 miliar tahun) karena pelapisan ulang vulkanik. Bulan tanpa atmosfer menerima setiap tumbukan sekecil apa pun dan tidak ada yang menghapusnya. Korosif karena awan asam sulfat (H₂SO₄) dan senyawa sulfur dari vulkanisme.`, R`Pendarat Venera hanya bertahan paling lama ~2 jam di permukaan.`),
   E('E29', R`Belum ada pendarat di Merkurius, tetapi kita yakin kawah besarnya berumur ~4 miliar tahun seperti di Bulan. Mengapa?`, R`Umur kawah Bulan diukur langsung dari sampel Apollo (penanggalan radiometrik). Kerapatan kawah per luas di permukaan tua Merkurius sama dengan di dataran tinggi Bulan; karena kedua benda dihujani populasi penumbuk yang sama di tata surya dalam, kerapatan kawah yang sama berarti umur yang sama (masa pengeboman berat).`, R`Ini metode "jam kawah" yang dikalibrasi Bulan.`),
   E('E30', R`Satelit-satelit Jupiter sebagian besar es. Suhu permukaannya lebih tinggi, lebih rendah, atau sama dengan suhu puncak awan Jupiter? Bagaimana perbandingan antarsatelit?`, R`Lebih rendah: satelit hanya dipanasi Matahari dan albedo esnya tinggi (memantulkan banyak), sedangkan Jupiter punya panas dalam. Antarsatelit hampir sama (jarak dari Matahari sama), sedikit berbeda karena albedo (Europa terang paling dingin ~100 K, Callisto gelap sedikit lebih hangat); Io lokal sangat panas di gunung apinya.`, R`Jupiter ~125 K di puncak awan; satelit Galileo ~100–130 K di siang hari.`),
   E('E31', R`Bila ada planet seukuran Bumi di dekat orbit Jupiter, bagaimana atmosfernya dibanding Bumi dan Jupiter? Adakah N₂ dan O₂?`, R`Sangat dingin (~120 K, atau ~100 K dengan albedo Bumi): air dan CO₂ membeku di permukaan; atmosfer tersisa N₂ (dan mungkin CH₄), seperti Titan. Dibanding Jupiter jauh lebih tipis dan tanpa H/He karena gravitasinya terlalu kecil untuk menahan H/He purba. N₂ mungkin ada; O₂ bebas hampir pasti tidak (di Bumi O₂ hasil fotosintesis).`, R`T ≈ 278 K/√5,2 = 122 K untuk benda hitam.`),
   E('E32', R`Menurut hukum Kepler, apa yang terjadi pada "jari-jari" (spoke) di cincin Saturnus? Seberapa cepat?`, R`Spoke radial akan terpuntir: bagian dalam cincin mengorbit lebih cepat daripada bagian luar. Di cincin B (92 000–117 580 km) periodenya 7,9 jam dan 11,4 jam, sehingga ujung dalam unggul satu putaran penuh atas ujung luar dalam ~26 jam; dalam sekitar 1 jam sudah miring ~14°. Jadi spoke harus lenyap atau tergulung dalam hitungan jam.`, R`P = 2π√(r³/GM), GM_Saturnus = 3,79 × 10¹⁶ m³/s². Kenyataannya spoke memang hanya bertahan beberapa jam, dan mula-mula berputar bersama medan magnet Saturnus (10,7 jam), tanda bahwa ia debu halus bermuatan listrik.`),
   E('E33', R`Bagaimana menentukan diameter Mars dari pengamatan di Bumi saja? (Petunjuk: hukum Kepler.)`, R`(1) Ukur periode sinodis Mars (780 hari) → periode sideris 687 hari → a = 1,524 SA (Kepler III). (2) Pada oposisi, jarak Bumi–Mars = 0,524 SA (koreksi eksentrisitas bila perlu). (3) Ubah SA ke km dengan paralaks/radar (mis. transit Venus atau radar ke Venus). (4) Ukur diameter sudut Mars di teleskop saat oposisi (~18–25″). Diameter = jarak × diameter sudut (rad).`, R`Contoh: 0,524 × 1,496 × 10⁸ km × 18″/206 265 = 6840 km (nyata 6779 km).`),
   E('E34', R`Lima barang untuk koloni jangka panjang di Mars dan alasannya.`, R`Misalnya: (1) habitat bertekanan dan pakaian antariksa (tekanan 0,6% Bumi membuat cairan tubuh mendidih); (2) sistem pembuat oksigen dan daur ulang udara/air (elektrolisis es, MOXIE dari CO₂); (3) sumber energi andal (reaktor nuklir kecil; sinar Matahari hanya 43% dan badai debu bisa berbulan-bulan); (4) perisai radiasi (tanpa medan magnet global dan atmosfer tebal; regolit sebagai pelindung); (5) rumah kaca, benih, dan alat pengolah tanah perklorat untuk pangan; ditambah peralatan medis dan suku cadang/printer 3D.`, R`Jawaban terbuka; nilai alasannya, bukan daftar persisnya.`),
   E('E35', R`Bagaimana siklus siang-malam di Venus? Ceritakan perjalanan ke permukaannya.`, R`Rotasi retrograd 243 hari + revolusi 224,7 hari → satu hari matahari 116,75 hari Bumi; Matahari terbit di barat dan terbenam di timur, tetapi tak terlihat di balik awan. Turun lewat awan asam sulfat di 50–70 km (di sana tekanan dan suhu mirip Bumi!), angin 360 km/jam (super-rotasi), lalu udara makin panas dan rapat; di permukaan 460 °C, 92 bar (seperti 900 m di bawah laut), cahaya jingga redup, siang dan malam sama panas.`, R`1/S = 1/243,0 + 1/224,7 → S = 116,75 hari (preset Venus di lab).`),
   E('E36', R`Bila sirkulasi atmosfer Bumi berhenti, bagaimana suhu di ekuator, lintang menengah, kutub?`, R`Ekuator makin panas, kutub makin dingin (kontras ekuator–kutub membesar drastis), lintang menengah berubah sedikit. Sirkulasi atmosfer dan laut kini mengangkut ~5 PW panas dari tropis ke kutub.`, R`Masing-masing lintang akan mendekati kesetimbangan radiasi lokal.`),
   E('E37', R`Satelit mengorbit dua planet yang tampak identik (tanpa bulan). Orbit satelit pertama elips sempurna, kedua hampir elips dengan percepatan kecil. Apa artinya bagi interior kedua planet?`, R`Planet pertama memiliki distribusi massa simetri bola (berlapis-lapis konsentris), sehingga bertindak seperti massa titik. Planet kedua memiliki massa yang tak merata (pepat karena rotasi, gunung/konsentrasi massa "mascon", inti tak di pusat), yang memberi gangguan gravitasi kecil.`, R`Cara inilah medan gravitasi Bulan (mascon di bawah maria) dan planet lain dipetakan (misi GRACE/GRAIL).`),
   E('E38', R`Bagaimana interior Uranus dan Neptunus berbeda dari Jupiter dan Saturnus?`, R`Jupiter/Saturnus: sebagian besar H/He, dengan lapisan hidrogen metalik tebal dan inti relatif kecil. Uranus/Neptunus: hanya ~10–20% H/He di selubung luar; sebagian besar adalah mantel "es" (fluida air–amonia–metana panas bertekanan tinggi) di atas inti batuan; tekanannya tidak cukup untuk hidrogen metalik. Medan magnetnya dibangkitkan di lapisan ionik air, sehingga miring dan tak berpusat.`, R`Kerapatannya (1,27 dan 1,64) lebih tinggi daripada Saturnus walau massanya jauh lebih kecil.`),
   E('E39', R`Atmosfer Mars > 90% CO₂ seperti Venus, mengapa efek rumah kacanya kecil? Mengapa atmosfernya tipis? Apa "runaway refrigerator"?`, R`Jumlah CO₂-nya sangat sedikit (tekanan 6 mbar vs 92 bar), sehingga hanya menghangatkan ~5 K. Tipis karena Mars kecil: gravitasi rendah, inti cepat dingin → medan magnet hilang → angin surya mengikis atmosfer; tanpa vulkanisme CO₂ tidak diisi ulang, dan sebagian terkunci di batuan karbonat/kutub. Runaway refrigerator: makin sedikit CO₂ → makin dingin → makin banyak CO₂ dan air membeku/terkunci → makin sedikit gas → makin dingin (umpan balik positif, kebalikan Venus).`, R`Bandingkan dengan lab zona air cair: rumah kaca 5 K tak cukup membawa Mars ke 273 K.`),
   E('E40', R`Mengapa satelit Saturnus (Titan) yang lebih ringan dari Mars bisa beratmosfer lebih tebal daripada Mars dan Bumi?`, R`Titan sangat dingin (~94 K), sehingga molekul N₂ bergerak lambat dan jauh di bawah kecepatan lepasnya (2,6 km/s); ia juga terlindung sebagian oleh magnetosfer Saturnus dan terbentuk di wilayah kaya es/amonia yang menyediakan nitrogen. Mars lebih hangat dan kehilangan atmosfer lewat pengikisan angin surya dan lolos termal.`, R`Syarat bertahannya gas kira-kira: kecepatan termal rata-rata < 1/6 kecepatan lepas.`),
   E('E41', R`Bagaimana jumlah kawah dipakai menentukan umur permukaan? Dataran tinggi Bulan punya kawah ~10× lebih banyak per luas daripada maria. Apakah dataran tinggi 10× lebih tua?`, R`Makin lama permukaan terbuka, makin banyak kawah terkumpul; kerapatan kawah dikalibrasi dengan sampel Apollo yang diberi umur radiometrik. Tetapi laju tumbukan tidak tetap: sangat tinggi sebelum ~3,8 miliar tahun lalu lalu turun drastis. Dataran tinggi (~4,4 miliar tahun) hanya sedikit lebih tua daripada maria (~3,2–3,8 miliar tahun), tetapi sempat mengalami masa pengeboman berat.`, R`Jadi umur tidak sebanding dengan jumlah kawah. Dataran tinggi bahkan sudah jenuh kawah (kawah baru menghapus kawah lama).`),
   E('E42', R`Mengapa Io sangat aktif secara geologi? Bagaimana interiornya tetap cair? Mengapa satelit Jupiter lain tidak seaktif itu?`, R`Pemanasan pasang surut: Io dekat sekali dengan Jupiter, dan resonansi orbit 1 : 2 : 4 dengan Europa dan Ganymede memaksa orbitnya tetap sedikit eksentrik. Jarak ke Jupiter berubah tiap orbit, sehingga tonjolan pasang surut Io (sampai ~100 m) mengembang-mengempis setiap 42,5 jam; gesekan internal mengubahnya menjadi panas. Satelit lain lebih jauh (gaya pasang surut ∝ 1/r³) dan/atau tidak dipaksa eksentrik.`, R`Europa masih cukup terpanasi untuk menjaga lautan di bawah es; Ganymede dan Callisto praktis tidak.`),
   E('E43', R`Bagaimana astronom menyimpulkan Uranus dan Neptunus bercincin dengan metode okultasi bintang?`, R`Saat planet akan menutupi bintang, cahaya bintang dipantau terus. Sebelum dan sesudah planet lewat, bintang meredup sesaat beberapa kali secara simetris di kedua sisi planet: tanda cincin sempit yang menghalangi cahaya. Dari waktu dan lama tiap kedipan diperoleh jari-jari dan lebar cincin.`, R`Uranus: Elliot dkk. 1977 (KAO). Neptunus: kedipan hanya di satu sisi (busur cincin Adams), dipastikan Voyager 2 (1989).`),
   E('E44', R`Teori-teori pembentukan tata surya beserta kelebihan dan kelemahannya.`, R`Sama dengan Review 3; lihat topik "Pembentukan tata surya".`, R`Tambahan modern: model Nice (migrasi planet raksasa) menjelaskan pengeboman berat akhir dan struktur sabuk Kuiper.`),
   E('E45', R`Mengapa lebih banyak meteor tampak dari tengah malam sampai fajar daripada dari senja sampai tengah malam?`, R`Setelah tengah malam pengamat berada di belahan Bumi yang menghadap arah gerak orbit Bumi (apeks), seperti kaca depan mobil di tengah hujan: Bumi "menyapu" meteoroid, dan kecepatan relatifnya lebih besar sehingga meteor lebih terang. Sebelum tengah malam hanya meteoroid yang "menyusul" Bumi yang masuk.`, R`Kecepatan meteor berkisar 11–72 km/s; yang paling cepat datang dari arah apeks.`),
   E('E46', R`Celah Kirkwood terjadi saat periode asteroid = pecahan bulat periode Jupiter. Hitung jaraknya untuk resonansi 1/2, 1/3, 2/3, 1/4; bandingkan dengan orbit Mars dan Jupiter.`, R`1/2: 3,28 SA; 1/3: 2,50 SA; 2/3: 3,97 SA; 1/4: 2,06 SA. Semuanya di antara Mars (1,52) dan Jupiter (5,20); 1/4 di tepi dalam sabuk dan 1/2 di tepi luarnya.`, R`a = 5,203 × (P/P_J)^{2/3}. Catatan: resonansi 2/3 (3,97 SA) justru dihuni asteroid Hilda (resonansi "menghimpun"), bukan celah.`),
   E('E47', R`Di jarak berapa dari Matahari air cair dapat ada di planet berotasi yang memancar sebagai benda hitam? Bandingkan dengan Venus, Bumi, Mars. Bagaimana pengaruh atmosfer?`, R`Antara ~0,56 SA (373 K) dan ~1,04 SA (273 K) untuk benda hitam sempurna (albedo 0). Venus (0,72) dan Bumi (1,00) di dalam zona, Mars (1,52) di luar. Atmosfer: albedo (awan) mendinginkan (dengan A = 0,3 zonanya 0,47–0,87 SA, Bumi di luar!), sedangkan efek rumah kaca menghangatkan (Bumi +33 K → 288 K; Venus +500 K → mendidih). Tekanan juga menentukan titik didih.`, R`\(T = 278{,}6\,\text{K}\,(1 - A)^{1/4}/\sqrt{d}\) dari keseimbangan \(\pi R^2 L/(4\pi d^2)(1-A) = 4\pi R^2 \sigma T^4\). Coba lab zona air cair.`),
   E('E48', R`(a) Cara mengetahui periode rotasi Matahari. (b) Evolusi Matahari. (c) Komposisi Matahari. (d) Penyebab pergeseran orbit Merkurius; apakah karena planet Vulcan? (e) Bagaimana posisi Neptunus diduga sebelum ditemukan?`, R`(a) Melacak bintik/fakula melintasi piringan (~27 hari sinodis, 25 hari sideris di ekuator) atau Doppler tepi timur–barat (±2 km/s). (b) Protobintang → deret utama ~10 miliar tahun (kini 4,6) → raksasa merah → kilatan helium → cabang horizontal → AGB → nebula planeter → katai putih. (c) Menurut massa ~73% H, 25% He, 2% unsur berat (O, C, Ne, Fe, …), dari analisis garis spektrum. (d) Bukan Vulcan (tidak pernah ditemukan); 43″/abad yang tak terjelaskan Newton dijelaskan relativitas umum. (e) Adams dan Le Verrier menghitung massa dan posisi planet pengganggu dari penyimpangan orbit Uranus; Galle menemukannya 1846 dalam 1° dari prediksi Le Verrier.`, R`Ironisnya, Le Verrier juga yang mengusulkan Vulcan untuk Merkurius, dengan metode yang sama yang sukses untuk Neptunus.`),
   E('E49', R`(a) Beda meteor, meteoroid, meteorit. (b) Mengapa ekor komet makin panjang mendekati Matahari? Bentuk orbit dan asal komet. (c) Peran penelitian meteorit. (d) Apa sabuk Kuiper dan di mana (bandingkan orbit Pluto)? (e) Peran planet Jovian sebagai pelindung Bumi.`, R`(a) Lihat materi benda kecil. (b) Makin dekat Matahari, makin banyak es menyublim (fluks ∝ 1/r²) dan makin kuat angin surya serta tekanan radiasi; orbit elips sangat lonjong (atau hampir parabola), asal sabuk Kuiper (periode pendek) dan awan Oort (periode panjang). (c) Meteorit = sampel bahan awal tata surya: umur 4,56 miliar tahun, komposisi asteroid, butir presolar dan isotop supernova, bahkan molekul organik. (d) Cakram benda es di luar Neptunus, ~30–50 SA; orbit Pluto (29,7–49,3 SA) berada di dalamnya, sehingga Pluto adalah objek sabuk Kuiper. (e) Gravitasi Jupiter dan Saturnus melontarkan banyak komet keluar atau menangkap/menghancurkannya (Shoemaker-Levy 9, 1994), sehingga mengurangi tumbukan ke Bumi.`, R`Peran (e) bersifat dua sisi: resonansi dengan Jupiter juga mengirim asteroid ke orbit dekat Bumi.`),
   E('E50', R`Hari di Mars ~2,5% lebih panjang dari Bumi, periode orbit 687 hari. Taksir beda hari sideris dan hari matahari rata-rata di Mars.`, R`≈ 2,2 menit (hari matahari lebih panjang).`, R`S − T ≈ S²/P = (1,025 hari)²/687 hari = 1,53 × 10⁻³ hari = 132 s. Data nyata: hari matahari 24 j 39 m 35 s, sideris 24 j 37 m 22 s, beda 2 m 13 s (preset Mars di lab).`)
  ] }
 ]
});
})();
